<header class="flex min-h-[80px] items-center justify-between gap-4 border-b border-slate-200 bg-white px-4 sm:px-8"><div class="flex items-center gap-3"><button type="button" @click="sidebarOpen=!sidebarOpen" aria-label="Buka menu" class="h-11 w-11 rounded-lg text-slate-600"><svg class="mx-auto h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path stroke-width="2" stroke-linecap="round" d="M4 6h16M4 12h16M4 18h16"/></svg></button><span class="text-sm font-semibold text-slate-700">Absensi kontributor</span></div><a href="/shifts" class="text-sm font-semibold text-brand-700">Atur jadwal →</a></header>
<section class="w-full max-w-full px-3 sm:px-5 lg:px-7 py-5 space-y-6" x-data="adminAttendanceData()"><div><p class="text-xs font-bold uppercase tracking-widest text-brand-700">Kehadiran tim</p><h1 class="mt-2 text-2xl font-extrabold text-slate-900">Absensi masuk</h1><p class="mt-2 text-sm text-slate-500">Jam, tanggal, dan lokasi GPS saat kontributor menekan Masuk. Semua waktu dalam WITA.</p></div><p x-show="error" x-text="error" role="alert" class="rounded-xl bg-red-50 p-4 text-sm text-red-700"></p><div class="flex flex-wrap gap-3 rounded-2xl border border-slate-200 bg-white p-5"><label class="text-xs font-semibold text-slate-600">Tanggal<input type="date" x-model="date" @change="load()" class="mt-2 block h-11 rounded-lg border border-slate-200 px-3 text-sm font-normal"></label><label class="min-w-[180px] flex-1 text-xs font-semibold text-slate-600">Cari nama<input type="search" x-model="search" placeholder="Nama kontributor…" class="mt-2 block h-11 w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label><button type="button" @click="load()" class="mt-auto h-11 rounded-lg border border-brand-200 px-4 text-sm font-semibold text-brand-700">Muat ulang</button></div><div class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="p-5"><h2 class="font-bold text-slate-900" x-text="dateLabel(date)"></h2><p class="mt-1 text-sm text-slate-500" x-text="rows.length+' orang sudah masuk'"></p></div><div class="overflow-x-auto"><table class="w-full min-w-[600px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-4">Nama kontributor</th><th class="p-4">Jam masuk · WITA</th><th class="p-4">Koordinat & akurasi</th><th class="p-4">Lokasi</th></tr></thead><tbody><template x-for="row in filtered" :key="row.id"><tr class="border-t border-slate-100"><td class="p-4 font-semibold" x-text="row.contributor_name"></td><td class="p-4 tabular-nums" x-text="time(row.checked_in_at)"></td><td class="p-4"><p class="font-mono text-xs" x-text="row.latitude+', '+row.longitude"></p><p class="mt-1 text-xs text-slate-500" x-text="'±'+Math.round(row.accuracy_m)+' meter'"></p></td><td class="p-4"><a :href="mapUrl(row)" target="_blank" rel="noopener noreferrer" class="font-semibold text-brand-700 underline">Lihat peta ↗</a></td></tr></template></tbody></table></div><p x-show="loading" class="p-8 text-center text-sm text-slate-500">Memuat absensi…</p><p x-show="!loading&&!filtered.length" class="p-8 text-center text-sm text-slate-500">Belum ada absensi yang cocok pada tanggal ini.</p></div></section>
